_B9:"precision mediump float;\n#define LOWPREC lowp\n// Uniforms look like they're shared between vertex and fragment shaders in GLSL, so we have to be careful to avoid name clashes\n\nuniform sampler2D gm_BaseTexture;\n\nuniform bool gm_PS_FogEnabled;\nuniform vec4 gm_FogColour;\nuniform bool gm_AlphaTestEnabled;\nuniform float gm_AlphaRefValue;\n\nvoid DoAlphaTest(vec4 SrcColour)\n{\n	if (gm_AlphaTestEnabled)\n	{\n		if (SrcColour.a <= gm_AlphaRefValue)\n		{\n			discard;\n		}\n	}\n}\n\nvoid DoFog(inout vec4 SrcColour, float fogval)\n{\n	if (gm_PS_FogEnabled)\n	{\n		SrcColour = mix(SrcColour, gm_FogColour, clamp(fogval, 0.0, 1.0)); \n	}\n}\n\n#define _YY_GLSLES_ 1\n//\n// Simple passthrough fragment shader\n//\nvarying vec2 v_vTexcoord;\nvarying vec4 v_vColour;\n\nuniform vec4 overlayColor; \nuniform float overlayCoeff;\nuniform float finalAlpha;\n\nvoid main()\n{\n	vec4 color = texture2D(gm_BaseTexture,v_vTexcoord);\n	float alpha = color.a;\n	\n	\n	//BS'd luminance formula\n	float luma = 0.299 * color.r + 0.587 * color.g + 0.114 * color.b;\n	\n	luma *= (1.0 + overlayCoeff * 0.15);\n	\n//	color.rgb -= 1 - overlayColor.a;\n	\n	//color.rgb += overlayColor.rgb*overlayCoeff*0.25;\n	//color.rgb *= overlayColor.rgb * overlayCoeff * 3.0; \n	\n\n	color.rgb = vec3(luma,luma,luma);\n	float oAlpha = alpha;\n	\n	\n	\n	color.rgb += overlayColor.rgb * 0.25;\n	color.rgb *= overlayColor.rgb * overlayCoeff;\n	\n	vec3 lumaCoeff = vec3(1.0+luma-0.45, 1.0+luma-0.5, 1.0-luma+0.45);\n	\n	color.rgb += lumaCoeff * 0.25;\n	color.rgb *= lumaCoeff;\n	//color.b *= 1-luma+0.5;\n	\n	\n    gl_FragColor = v_vColour * color;\n	//gl_FragColor.a = alpha;\n	//gl_FragColor.a *= finalAlpha;\n}\n",
